actions.script:
const STALE = 10 * 60 * 1000
const counts = ec.cache.getCache('tools.home.counts')
let kept = null
try { kept = JSON.parse(counts.get('screens') || 'null') } catch (error) { kept = null }
screenCount = kept && kept.count != null ? Number(kept.count) : null
counting = !kept || Date.now() - Number(kept.time || 0) > STALE
if (counting) {
    // the time is now, so the renders of the next ten minutes do not ask again
    counts.put('screens', JSON.stringify({count: screenCount, time: Date.now()}))
    ec.service.async().name('moqui.tools.ToolsHomeServices.count#Screens').call()
}

let count = 0
for (const rootLocation of Array.from(ec.screen.getAllRootScreenLocations() || [])) {
    try {
        const rows = ec.screen.getScreenInfoList(rootLocation, 1)
        if (rows.length) count += 1 + Number(rows[0].allSubscreens || 0)
    } catch (error) {
        ec.logger.error('Tools home: the screens under ' + rootLocation + ' were not counted: ' + String(error))
    }
}
ec.cache.getCache('tools.home.counts').put('screens', JSON.stringify({count, time: Date.now()}))
screenCount = count
